/// <summary>
/// Append-only log tail: copies only new bytes to a permanent backup.
/// Never shrinks or deletes the backup. Handles truncate/recreate by syncing offset without re-copying.
/// </summary>
public sealed class LogTailMonitor
{
    private readonly OffsetStore _offsetStore;
    private readonly object _sync = new();
    private CancellationTokenSource? _cts;
    private Task? _loop;
    private bool _firstSeen = true;

    public MonitorOptions Options { get; private set; }
    public MonitorStatus Status { get; } = new();

    public event Action<MonitorStatus>? StatusChanged;
    public event Action<ActivityEntry>? Activity;

    public LogTailMonitor(MonitorOptions options, OffsetStore? offsetStore = null)
    {
        Options = options;
        _offsetStore = offsetStore ?? new OffsetStore();
        Status.OffsetBytes = _offsetStore.Load();
        Status.SourcePath = options.SourcePath;
        Status.BackupPath = options.BackupPath;
    }

    public void UpdateOptions(MonitorOptions options)
    {
        lock (_sync)
        {
            Options = options;
            Status.SourcePath = options.SourcePath;
            Status.BackupPath = options.BackupPath;
        }
    }

    public void Start()
    {
        lock (_sync)
        {
            if (_loop is { IsCompleted: false })
                return;

            _cts = new CancellationTokenSource();
            Status.IsRunning = true;
            Status.State = "Watching";
            Status.LastError = null;
            Publish("Info", "Monitor iniciado.");
            _loop = Task.Run(() => RunAsync(_cts.Token));
        }
    }

    public async Task StopAsync()
    {
        CancellationTokenSource? cts;
        Task? loop;
        lock (_sync)
        {
            cts = _cts;
            loop = _loop;
            _cts = null;
            _loop = null;
        }

        if (cts is null)
            return;

        cts.Cancel();
        try
        {
            if (loop is not null)
                await loop.ConfigureAwait(false);
        }
        catch (OperationCanceledException)
        {
            // expected
        }
        finally
        {
            cts.Dispose();
            Status.IsRunning = false;
            Status.State = "Stopped";
            Publish("Info", "Monitor parado.");
            FlushStatus();
        }
    }

    private async Task RunAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            try
            {
                Tick();
            }
            catch (Exception ex)
            {
                Status.State = "Error";
                Status.LastError = ex.Message;
                Publish("Error", ex.Message);
                FlushStatus();
            }

            try
            {
                await Task.Delay(Math.Max(250, Options.PollIntervalMs), token).ConfigureAwait(false);
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private void Tick()
    {
        MonitorOptions options;
        lock (_sync)
            options = Options;

        Status.LastPollUtc = DateTimeOffset.UtcNow;
        Status.SourcePath = options.SourcePath;
        Status.BackupPath = options.BackupPath;

        if (string.IsNullOrWhiteSpace(options.SourcePath) || string.IsNullOrWhiteSpace(options.BackupPath))
        {
            Status.State = "Config";
            Status.LastMessage = "Defina origem e backup.";
            FlushStatus();
            return;
        }

        if (!File.Exists(options.SourcePath))
        {
            Status.State = "Waiting";
            Status.SourceSizeBytes = 0;
            Status.LastMessage = "Aguardando arquivo de origem...";
            FlushStatus();
            return;
        }

        var sourceInfo = new FileInfo(options.SourcePath);
        var sourceLength = sourceInfo.Length;
        Status.SourceSizeBytes = sourceLength;

        if (File.Exists(options.BackupPath))
            Status.BackupSizeBytes = new FileInfo(options.BackupPath).Length;
        else
            Status.BackupSizeBytes = 0;

        var offset = Status.OffsetBytes;

        // First run: optionally start from end (do not backfill historical content).
        if (_firstSeen && options.StartFromEndOnFirstRun && offset == 0 && sourceLength > 0)
        {
            offset = sourceLength;
            Status.OffsetBytes = offset;
            _offsetStore.Save(offset);
            _firstSeen = false;
            Publish("Info", $"Primeira execução: offset definido no fim ({FormatBytes(offset)}).");
            Status.State = "Watching";
            FlushStatus();
            return;
        }

        _firstSeen = false;

        // Truncate / recreate: sync offset to current source size — never re-append existing bytes to backup.
        if (sourceLength < offset)
        {
            Status.TruncateEvents++;
            Publish("Warn", $"Arquivo truncado/recriado ({FormatBytes(sourceLength)} < offset {FormatBytes(offset)}). Backup preservado; offset sincronizado.");
            offset = sourceLength;
            Status.OffsetBytes = offset;
            _offsetStore.Save(offset);
        }

        if (sourceLength == offset)
        {
            Status.State = "Watching";
            Status.LastMessage = "Sem alterações.";
            FlushStatus();
            return;
        }

