        Status.LastCopyUtc = DateTimeOffset.UtcNow;
        Status.State = "Watching";
        Status.LastMessage = $"Copiados {FormatBytes(bytesToCopy)}.";
        Status.LastError = null;

        if (File.Exists(options.BackupPath))
            Status.BackupSizeBytes = new FileInfo(options.BackupPath).Length;

