namespace CanonCopy.Core;

public sealed class OffsetStore
{
    private readonly string _path;

    public OffsetStore(string? path = null)
    {
        _path = path ?? AppPaths.OffsetFile;
    }

    public long Load()
    {
        AppPaths.EnsureRoot();
        if (!File.Exists(_path))
            return 0;

        var text = File.ReadAllText(_path).Trim();
        return long.TryParse(text, out var value) && value >= 0 ? value : 0;
    }

    public void Save(long offset)
    {
        AppPaths.EnsureRoot();
        var temp = _path + ".tmp";
        File.WriteAllText(temp, offset.ToString());
        File.Copy(temp, _path, overwrite: true);
        File.Delete(temp);
    }
}

using System.Text.Json;

namespace CanonCopy.Core;

public static class StatusStore
{
    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        WriteIndented = true,
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase
    };

    private static readonly object Gate = new();

    public static MonitorStatus Load()
    {
        AppPaths.EnsureRoot();
        if (!File.Exists(AppPaths.StatusFile))
            return new MonitorStatus();

        try
        {
            var json = File.ReadAllText(AppPaths.StatusFile);
            return JsonSerializer.Deserialize<MonitorStatus>(json, JsonOptions) ?? new MonitorStatus();
        }
        catch
        {
            return new MonitorStatus();
        }
    }

    public static void Save(MonitorStatus status)
    {
        AppPaths.EnsureRoot();
        status.UpdatedUtc = DateTimeOffset.UtcNow;
        var json = JsonSerializer.Serialize(status, JsonOptions);
        var temp = AppPaths.StatusFile + ".tmp";
        lock (Gate)
        {
            File.WriteAllText(temp, json);
            File.Copy(temp, AppPaths.StatusFile, overwrite: true);
            File.Delete(temp);
        }
    }

    public static void AppendActivity(ActivityEntry entry, int keepLast = 200)
    {
        AppPaths.EnsureRoot();
        var line = JsonSerializer.Serialize(entry, JsonOptions);
        lock (Gate)
        {
            File.AppendAllText(AppPaths.ActivityFile, line + Environment.NewLine);

            if (!File.Exists(AppPaths.ActivityFile))
                return;

            var lines = File.ReadAllLines(AppPaths.ActivityFile);
            if (lines.Length <= keepLast)
                return;

            File.WriteAllLines(AppPaths.ActivityFile, lines.TakeLast(keepLast));
        }
    }

    public static IReadOnlyList<ActivityEntry> LoadActivity(int max = 80)
    {
        AppPaths.EnsureRoot();
        if (!File.Exists(AppPaths.ActivityFile))
            return Array.Empty<ActivityEntry>();

        try
        {
            var lines = File.ReadAllLines(AppPaths.ActivityFile);
            return lines
                .Reverse()
                .Take(max)
                .Select(l =>
                {
                    try { return JsonSerializer.Deserialize<ActivityEntry>(l, JsonOptions); }
                    catch { return null; }
                })
                .Where(e => e is not null)
                .Cast<ActivityEntry>()
                .ToList();
        }
        catch
        {
            return Array.Empty<ActivityEntry>();
        }
    }
}

