using CanonCopy.Core;

namespace CanonCopy.Service;

public sealed class LogGuardWorker : BackgroundService
{
    private readonly ILogger<LogGuardWorker> _logger;
    private LogTailMonitor? _monitor;
    private DateTime _lastConfigCheck = DateTime.MinValue;
    private string _configStamp = string.Empty;

    public LogGuardWorker(ILogger<LogGuardWorker> logger)
    {
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        AppPaths.EnsureRoot();
        _logger.LogInformation("CanonCopy Log Guard iniciando...");

        var options = ConfigStore.Load();
        _monitor = new LogTailMonitor(options);
        _monitor.Start();

        try
        {
            while (!stoppingToken.IsCancellationRequested)
            {
                ReloadConfigIfChanged();
                await Task.Delay(TimeSpan.FromSeconds(2), stoppingToken).ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException)
        {
            // shutdown
        }
        finally
        {
            if (_monitor is not null)
                await _monitor.StopAsync().ConfigureAwait(false);

            _logger.LogInformation("CanonCopy Log Guard encerrado.");
        }
    }

    private void ReloadConfigIfChanged()
    {
        try
        {
            if (!File.Exists(AppPaths.ConfigFile))
                return;

            var info = new FileInfo(AppPaths.ConfigFile);
            var stamp = $"{info.Length}:{info.LastWriteTimeUtc.Ticks}";
            if (stamp == _configStamp && (DateTime.UtcNow - _lastConfigCheck) < TimeSpan.FromSeconds(5))
                return;

            _lastConfigCheck = DateTime.UtcNow;
            if (stamp == _configStamp)
                return;

            _configStamp = stamp;
            var options = ConfigStore.Load();
            _monitor?.UpdateOptions(options);
            _logger.LogInformation("Configuração recarregada: {Source} → {Backup}", options.SourcePath, options.BackupPath);
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "Falha ao recarregar configuração");
        }
    }
}

