﻿using System.Windows;

using System.Windows.Controls;

using System.Windows.Data;

using System.Globalization;

using System.Windows.Media;

using System.Windows.Media.Animation;



namespace CanonCopy.UI;



public partial class MainWindow : Window

{

    private readonly MainViewModel _vm;

    private const double NarrowBreakpoint = 1024;



    public MainWindow()

    {

        InitializeComponent();

        _vm = new MainViewModel();

        DataContext = _vm;

        Loaded += OnLoaded;

        SizeChanged += OnSizeChanged;

        _vm.PropertyChanged += (_, e) =>

        {

            if (e.PropertyName is nameof(MainViewModel.IsWatching) or nameof(MainViewModel.IsLocalRunning))

                UpdatePulse();

        };

    }



    private void OnLoaded(object sender, RoutedEventArgs e)

    {

        UpdatePulse();

        ApplyResponsiveLayout(ActualWidth);

    }



    private void OnSizeChanged(object sender, SizeChangedEventArgs e) =>

        ApplyResponsiveLayout(e.NewSize.Width);



    private void ApplyResponsiveLayout(double width)

    {

        if (PanelsGrid is null || LeftCol is null || MidCol is null || RightCol is null)

            return;



        if (width < NarrowBreakpoint)

        {

            PanelsGrid.ColumnDefinitions[0].Width = new GridLength(1, GridUnitType.Star);

            PanelsGrid.ColumnDefinitions[1].Width = new GridLength(0);

            PanelsGrid.ColumnDefinitions[2].Width = new GridLength(1, GridUnitType.Star);



            Grid.SetColumn(PanelsGrid.Children[0], 0);

            Grid.SetRow(PanelsGrid.Children[0], 0);

            Grid.SetColumn(PanelsGrid.Children[1], 0);

            Grid.SetRow(PanelsGrid.Children[1], 2);



            if (PanelsGrid.RowDefinitions.Count == 0)

            {

                PanelsGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

                PanelsGrid.RowDefinitions.Add(new RowDefinition { Height = new GridLength(16) });

                PanelsGrid.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            }

        }

        else

        {

            PanelsGrid.ColumnDefinitions[0].Width = new GridLength(1.1, GridUnitType.Star);

            PanelsGrid.ColumnDefinitions[1].Width = new GridLength(16);

            PanelsGrid.ColumnDefinitions[2].Width = new GridLength(0.9, GridUnitType.Star);



            Grid.SetColumn(PanelsGrid.Children[0], 0);

            Grid.SetRow(PanelsGrid.Children[0], 0);

            Grid.SetColumn(PanelsGrid.Children[1], 2);

            Grid.SetRow(PanelsGrid.Children[1], 0);

        }

    }



    private void UpdatePulse()

    {

        PulseRing.BeginAnimation(OpacityProperty, null);

        var scale = PulseRing.RenderTransform as ScaleTransform;

        scale?.BeginAnimation(ScaleTransform.ScaleXProperty, null);

        scale?.BeginAnimation(ScaleTransform.ScaleYProperty, null);



        if (!_vm.IsWatching && !_vm.IsLocalRunning)

        {

            PulseRing.Opacity = 0.25;

            return;

        }



        var opacityAnim = new DoubleAnimation(0.9, 0.2, new Duration(TimeSpan.FromMilliseconds(1300)))

        {

            AutoReverse = true,

            RepeatBehavior = RepeatBehavior.Forever,

            EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseInOut }

        };

        var scaleAnim = new DoubleAnimation(1, 1.5, new Duration(TimeSpan.FromMilliseconds(1300)))

        {

            AutoReverse = true,

            RepeatBehavior = RepeatBehavior.Forever,

            EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseInOut }

        };



        PulseRing.BeginAnimation(OpacityProperty, opacityAnim);

        scale?.BeginAnimation(ScaleTransform.ScaleXProperty, scaleAnim);

        scale?.BeginAnimation(ScaleTransform.ScaleYProperty, scaleAnim);

    }

}



