using System.Diagnostics;
using System.IO;
using System.ServiceProcess;

namespace CanonCopy.UI;

public static class ServiceHelper
{
    public const string ServiceName = "CanonCopyLogGuard";
    public const string DisplayName = "CanonCopy Log Guard";

    public static string? FindServiceExe()
    {
        var baseDir = AppContext.BaseDirectory;
        var candidates = new[]
        {
            Path.GetFullPath(Path.Combine(baseDir, "..", "..", "..", "..", "CanonCopy.Service", "bin", "Debug", "net8.0-windows", "CanonCopy.Service.exe")),
            Path.GetFullPath(Path.Combine(baseDir, "..", "..", "..", "..", "CanonCopy.Service", "bin", "Release", "net8.0-windows", "CanonCopy.Service.exe")),
            Path.Combine(baseDir, "CanonCopy.Service.exe"),
            Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), "CanonCopy", "CanonCopy.Service.exe")
        };

        return candidates.FirstOrDefault(File.Exists);
    }

    public static bool IsInstalled()
    {
        try
        {
            using var sc = new ServiceController(ServiceName);
            _ = sc.Status;
            return true;
        }
        catch
        {
            return false;
        }
    }

    public static string GetStatusText()
    {
        try
        {
            using var sc = new ServiceController(ServiceName);
            return sc.Status.ToString();
        }
        catch
        {
            return "NotInstalled";
        }
    }

    public static async Task<(bool Ok, string Message)> InstallAsync()
    {
        var exe = FindServiceExe();
        if (exe is null)
            return (false, "CanonCopy.Service.exe não encontrado. Compile o projeto Service primeiro.");

        if (IsInstalled())
            return (true, "Serviço já instalado.");

        var psi = new ProcessStartInfo
        {
            FileName = "sc.exe",
            Arguments = $"create \"{ServiceName}\" binPath= \"\\\"{exe}\\\"\" start= auto DisplayName= \"{DisplayName}\"",
            UseShellExecute = true,
            Verb = "runas",
            CreateNoWindow = true
        };

        try
        {
            using var p = Process.Start(psi);
            if (p is null)
                return (false, "Não foi possível elevar privilégios.");
            await p.WaitForExitAsync().ConfigureAwait(false);
            if (p.ExitCode != 0)
                return (false, $"sc create falhou (código {p.ExitCode}).");

            // Description
            var desc = new ProcessStartInfo
            {
                FileName = "sc.exe",
                Arguments = $"description \"{ServiceName}\" \"Monitor append-only de logs CanonCopy. Nunca apaga o backup.\"",
                UseShellExecute = true,
                Verb = "runas",
                CreateNoWindow = true
            };
            using var d = Process.Start(desc);
            if (d is not null)
                await d.WaitForExitAsync().ConfigureAwait(false);

            return (true, "Serviço instalado. Pode iniciar.");
        }
        catch (Exception ex)
        {
            return (false, ex.Message);
        }
    }

    public static async Task<(bool Ok, string Message)> StartAsync()
    {
        return await RunScAsync($"start \"{ServiceName}\"", "Serviço iniciado.");
    }

    public static async Task<(bool Ok, string Message)> StopAsync()
    {
        return await RunScAsync($"stop \"{ServiceName}\"", "Serviço parado.");
    }

    public static async Task<(bool Ok, string Message)> UninstallAsync()
    {
        if (IsInstalled())
        {
            try { await StopAsync().ConfigureAwait(false); } catch { /* ignore */ }
        }

        return await RunScAsync($"delete \"{ServiceName}\"", "Serviço removido.");
    }

    private static async Task<(bool Ok, string Message)> RunScAsync(string args, string okMessage)
    {
        try
        {
            var psi = new ProcessStartInfo
            {
                FileName = "sc.exe",
                Arguments = args,
                UseShellExecute = true,
                Verb = "runas",
                CreateNoWindow = true
            };
            using var p = Process.Start(psi);
            if (p is null)
                return (false, "Não foi possível elevar privilégios.");
            await p.WaitForExitAsync().ConfigureAwait(false);
            return p.ExitCode == 0
                ? (true, okMessage)
                : (false, $"Comando falhou (código {p.ExitCode}).");
        }
        catch (Exception ex)
        {
            return (false, ex.Message);
        }
    }
}

