using System.Diagnostics;

namespace CanonCopy.UI;

public sealed class SystemMetrics
{
    private readonly Process _process = Process.GetCurrentProcess();
    private TimeSpan _lastCpuTime;
    private DateTime _lastSampleUtc = DateTime.UtcNow;
    private bool _initialized;

    public double SampleCpuPercent()
    {
        _process.Refresh();
        var now = DateTime.UtcNow;
        var cpuTime = _process.TotalProcessorTime;

        if (!_initialized)
        {
            _initialized = true;
            _lastCpuTime = cpuTime;
            _lastSampleUtc = now;
            return 0;
        }

        var elapsedMs = (now - _lastSampleUtc).TotalMilliseconds;
        if (elapsedMs < 100)
            return 0;

        var cpuDeltaMs = (cpuTime - _lastCpuTime).TotalMilliseconds;
        var percent = cpuDeltaMs / (Environment.ProcessorCount * elapsedMs) * 100.0;

        _lastCpuTime = cpuTime;
        _lastSampleUtc = now;

        return Math.Clamp(percent, 0, 100);
    }

    public long SampleRamBytes()
    {
        _process.Refresh();
        return _process.WorkingSet64;
    }
}

