namespace CanonCopy.UI.Controls;

public partial class SparklineControl : UserControl
{
    public static readonly DependencyProperty PointsProperty =
        DependencyProperty.Register(nameof(Points), typeof(IEnumerable<double>), typeof(SparklineControl),
            new PropertyMetadata(null, OnPointsChanged));

    public static readonly DependencyProperty StrokeBrushProperty =
        DependencyProperty.Register(nameof(StrokeBrush), typeof(Brush), typeof(SparklineControl),
            new PropertyMetadata(new SolidColorBrush(Color.FromRgb(0x2E, 0xC4, 0xB6)), OnVisualChanged));

    public static readonly DependencyProperty FillBrushProperty =
        DependencyProperty.Register(nameof(FillBrush), typeof(Brush), typeof(SparklineControl),
            new PropertyMetadata(new SolidColorBrush(Color.FromArgb(0x33, 0x2E, 0xC4, 0xB6)), OnVisualChanged));

    public static readonly DependencyProperty ShowFillProperty =
        DependencyProperty.Register(nameof(ShowFill), typeof(bool), typeof(SparklineControl),
            new PropertyMetadata(false, OnVisualChanged));

    private INotifyCollectionChanged? _subscribed;

    public IEnumerable<double>? Points
    {
        get => (IEnumerable<double>?)GetValue(PointsProperty);
        set => SetValue(PointsProperty, value);
    }

    public Brush StrokeBrush
    {
        get => (Brush)GetValue(StrokeBrushProperty);
        set => SetValue(StrokeBrushProperty, value);
    }

    public Brush FillBrush
    {
        get => (Brush)GetValue(FillBrushProperty);
        set => SetValue(FillBrushProperty, value);
    }

    public bool ShowFill
    {
        get => (bool)GetValue(ShowFillProperty);
        set => SetValue(ShowFillProperty, value);
    }

    public SparklineControl()
    {
        InitializeComponent();
        Loaded += (_, _) => Redraw();
        SizeChanged += (_, _) => Redraw();
    }

    private static void OnPointsChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
    {
        if (d is not SparklineControl ctrl)
            return;

        if (ctrl._subscribed is not null)
            ctrl._subscribed.CollectionChanged -= ctrl.OnCollectionChanged;

        ctrl._subscribed = e.NewValue as INotifyCollectionChanged;
        if (ctrl._subscribed is not null)
            ctrl._subscribed.CollectionChanged += ctrl.OnCollectionChanged;

        ctrl.Redraw();
    }

    private static void OnVisualChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
    {
        if (d is SparklineControl ctrl)
            ctrl.Redraw();
    }

    private void OnCollectionChanged(object? sender, NotifyCollectionChangedEventArgs e) => Redraw();

    private void Redraw()
    {
        if (ActualWidth <= 0 || ActualHeight <= 0)
            return;

        var data = Points?.ToArray() ?? Array.Empty<double>();
        if (data.Length == 0)
        {
            SparkPath.Data = null;
            SparkLine.Points.Clear();
            return;
        }

        var width = ActualWidth;
        var height = ActualHeight;
        var max = data.Max();
        var min = data.Min();
        var range = max - min;
        if (range < 0.001)
            range = max > 0 ? max : 1;

        var stepX = data.Length == 1 ? 0 : width / (data.Length - 1);
        var points = new PointCollection(data.Length);

        for (var i = 0; i < data.Length; i++)
        {
            var normalized = (data[i] - min) / range;
            var x = i * stepX;
            var y = height - (normalized * (height - 4)) - 2;
            points.Add(new Point(x, y));
        }

        if (ShowFill && points.Count > 1)
        {
            var figure = new PathFigure { StartPoint = points[0], IsClosed = true, IsFilled = true };
            for (var i = 1; i < points.Count; i++)
                figure.Segments.Add(new LineSegment(points[i], true));
            figure.Segments.Add(new LineSegment(new Point(points[^1].X, height), true));
            figure.Segments.Add(new LineSegment(new Point(points[0].X, height), true));

            SparkPath.Data = new PathGeometry(new[] { figure });
            SparkLine.Visibility = Visibility.Collapsed;
        }
        else
        {
            SparkPath.Data = null;
            SparkLine.Points = points;
            SparkLine.Visibility = Visibility.Visible;
        }
    }
}
